// ─── File: ConsistentHashDemo.java ───
// Runnable demo: adding a shard — MODULO remaps most keys; the RING moves ~1/N keys.
package com.bank.conshash;

import java.util.*;
import java.util.logging.*;

public class ConsistentHashDemo {

    private static final Logger log = Logger.getLogger("ConsHash");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<String> keys = new ArrayList<>();
        for (int i = 1; i <= 10_000; i++) keys.add("CUST" + (1000 + i));

        // ── MODULO: add a 5th shard → count how many keys move ──
        ModuloSharder mod4 = new ModuloSharder(4), mod5 = new ModuloSharder(5);
        long moved = keys.stream().filter(k -> mod4.shardOf(k) != mod5.shardOf(k)).count();
        log.severe(() -> "MODULO 4→5 shards: " + moved + "/" + keys.size()
                + " keys moved (" + (100 * moved / keys.size()) + "%) ← almost everything");

        // ── CONSISTENT HASH: add a shard → count how many keys move ──
        ConsistentHashRing ring = new ConsistentHashRing(150);  // 150 vnodes per shard
        for (int i = 0; i < 4; i++) ring.addShard("shard" + i);
        Map<String, String> before = new HashMap<>();
        for (String k : keys) before.put(k, ring.shardOf(k));
        ring.addShard("shard4");                                 // add the 5th shard
        long ringMoved = keys.stream().filter(k -> !ring.shardOf(k).equals(before.get(k))).count();
        log.info(() -> "CONSISTENT HASH +1 shard: " + ringMoved + "/" + keys.size()
                + " keys moved (" + (100 * ringMoved / keys.size()) + "%) ← ~1/N only");

        // Distribution with virtual nodes stays even.
        Map<String, Integer> dist = new TreeMap<>();
        for (String k : keys) dist.merge(ring.shardOf(k), 1, Integer::sum);
        log.info(() -> "ring distribution (vnodes smooth it): " + dist);
    }
}

// ─── modulo/ModuloSharder.java (naive hash % N) ───
class ModuloSharder {
    private final int n;
    ModuloSharder(int n) { this.n = n; }
    int shardOf(String key) { return Math.floorMod(key.hashCode(), n); }   // N in the formula → fragile
}

// ─── ring/ConsistentHashRing.java (ring + virtual nodes) ───
class ConsistentHashRing {
    private final int vnodes;
    private final TreeMap<Integer, String> ring = new TreeMap<>();   // ring position → shard
    ConsistentHashRing(int vnodes) { this.vnodes = vnodes; }
    void addShard(String shard) {
        for (int v = 0; v < vnodes; v++)
            ring.put(hash(shard + "#vn" + v), shard);   // many points per physical shard
    }
    void removeShard(String shard) { ring.values().removeIf(s -> s.equals(shard)); }
    // Walk clockwise to the first shard point at or after the key's position.
    String shardOf(String key) {
        int h = hash(key);
        Map.Entry<Integer, String> e = ring.ceilingEntry(h);
        if (e == null) e = ring.firstEntry();           // wrap around the ring
        return e.getValue();
    }
    private int hash(String s) { return s.hashCode() & 0x7fffffff; }   // non-negative ring position
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
